#!/bin/zsh
# Saison 2 : 3e passe : Dexter (confiture sur l armure) et Conan (le héros pousse seul, le barbare donne les ordres) avec les vues en pied du héros (hero_s2/sel_*.png), tourné vers son
# interlocuteur, avec une expression précise, plus de sourire figé (demande de Stéphan du 24/11).
# FLUX 3 Klein local, file calcul-lourd. Relançable : saute ce qui existe. Usage : gen_s2_scenes_vues3.sh [id…]
cd "$(dirname "$0")/../work/crossover" || exit 1
ST="hand-painted 2000s 2D point-and-click adventure game scene, painterly detailed backgrounds like classic adventure games, bold dark outlines, warm saturated colors, humorous storybook fantasy, characters with realistic adult proportions and ironic expressions, wide composition, no logo, no watermark, no frame, no text, no letters"
STL="hand-painted 2000s 2D point-and-click adventure game scene, painterly detailed backgrounds like classic adventure games, bold dark outlines, warm saturated colors, humorous storybook fantasy, characters with realistic adult proportions and ironic expressions, wide composition, no logo, no watermark, no frame"
H="The hero is exactly the man from the reference picture: same face, same blond ponytail, same horned iron Viking helmet, same fur-collared studded leather armor, same round wooden shield strapped on his back, same pleated brown leather kilt with leather pouches, same fur-topped boots, same painted style; NOT a tartan kilt. His usual smirk is gone, no smile at all."
L34="He is seen in three-quarter view, his chest, feet and face turned toward the LEFT side of the picture"
R34="He is seen in three-quarter view, his chest, feet and face turned toward the RIGHT side of the picture"
VIL="a blocky villager made entirely of big square cubes, with a huge long rectangular nose, a single bushy unibrow, a long brown robe and his arms folded together in front of him"
CR="a tall green creature made of cubes, with four short stubby block legs, no arms and a sad dark pixel face"
DOC="a tall lanky old scientist with realistic adult proportions and a normal-sized head, a shock of wild white hair, wide excited eyes, a white lab coat over a dark shirt, protective goggles pushed up on his forehead"
HO="a sardonic doctor in his late forties with short messy dark brown hair, intense blue eyes and heavy stubble, a charcoal grey suit blazer over an open-collared light blue shirt with a white t-shirt underneath, dark trousers and sneakers, no lab coat, a bored contemptuous stare"
PA="a clean-shaven middle-aged paleontologist with short greying brown hair, a light straw wide-brimmed hat with a dark band, a long-sleeved blue denim shirt with rolled-up sleeves, a red bandana knotted around his neck, beige khaki trousers and brown boots"
AR="a weary medieval king in his forties with long messy dark curly hair falling to his shoulders, a thin ornate gold circlet diadem across his forehead instead of a crown, a short dark goatee and stubble, a dark burgundy red wool tunic, a dark brown studded leather cuirass with buckled shoulder straps and an embossed dragon motif, a black scarf at the neck, a sceptical sidelong glance"
PE="a lanky medieval knight in his forties with messy shoulder-length greying blond hair and a short scruffy beard, a blue quilted padded gambeson closed with leather tabs and laces, a grey wool hooded cloak fastened with a small brass clasp, brown laced leather bracers, a sword in a brown leather scabbard at his hip, a blank vacant stare"
KA="a stout round-faced medieval knight with short dark brown hair and a few days of stubble, a chainmail hauberk, a red wool cloak with a red hood collar draped over his shoulders, leather straps"
CO="a towering massively muscular barbarian with long straight light brown hair to his shoulders, a studded dark leather headband, a few black war paint stripes across his face and shoulders, bare tanned torso, a pendant necklace, a fur loincloth under a wide brown leather belt, dark leather wrist bracers, fur boots, his long sword strapped on his back, a stern stare"
KID="three boys of about twelve with realistic child proportions, bowl haircuts, one in a blue and white trucker cap, raglan t-shirts, jeans and sneakers, each holding a big walkie-talkie"
DX="a polite forensic analyst in his thirties with tousled light brown hair, a sly polite half-smile and calm watchful eyes, wearing a short-sleeved coral orange polo shirt with a chest pocket and a pair of sunglasses hooked in its open placket, khaki trousers"
MO="a calm tall bald Black man with dark brown skin, small round dark pince-nez sunglasses, a long dark green-black leather coat over a dark vest and tie"
AI="a large sleek white robotic artificial intelligence hanging down from the ceiling on a black mechanical arm, a smooth white head shell with a single round glowing yellow eye"
typeset -A P R
P[r_dexterw]="$H $R34, toward the analyst; he looks uneasy: a nervous sideways glance at the analyst, a forced tight-lipped grimace, a bead of sweat on his temple. His studded leather armor and fur collar are covered with big messy splatters of bright pink raspberry jam and birthday cake crumbs. A tidy sunny Miami police forensic lab: microscopes, glass slides, a window showing palm trees and the sea. In the background, a small room covered in clear plastic sheeting. Two separate people, from left to right: first the hero; second $DX, holding an open box of donuts in one hand and with the other hand holding a magnifying glass close to the jam splatters on the hero's chest, studying them with keen interest. Each person wears only his own clothes. $ST"; R[r_dexterw]=hero_s2/sel_34_right.png
P[r_conanw]="$H He is seen in strict side profile facing LEFT, walking to the left, leaning far forward, pushing with both hands and his chest against the end of one long horizontal wooden beam of a capstan; his face shows exhausting strain: teeth gritted, eyes squeezed half shut, red cheeks, drops of sweat. A barren snowy plain under a grey sky. In the centre, a big horizontal wooden mill capstan: a thick wooden post with long horizontal wooden beams at waist height, and a circular path worn into the snow around it; the hero walks along that path, alone at the beams. On the right, $CO stands still with his arms crossed, watching him sternly, not pushing. Each person wears only his own clothes. In the sky flies a long serpentine luck dragon with no wings at all, covered in white fur and pearly pink scales, with a big friendly dog-like head and floppy ears, undulating through the air like a snake. On the horizon, a dark swirling void of nothingness eats the landscape. $ST"; R[r_conanw]=hero_s2/sel_profile_left.png
# 4e passe Conan : la poutre poussée doit être perpendiculaire à la marche (sinon elle ne tourne pas).
CAP="A barren snowy plain under a grey sky, seen from a high three-quarter angle. In the centre, a big wooden mill capstan: a thick vertical wooden post with four long horizontal wooden beams radiating from it like the spokes of a wheel at waist height, and a circular path worn into the snow around it. One beam points straight toward the viewer; the hero stands at its outer end and pushes against the SIDE of that beam, perpendicular to it, so that the whole capstan turns; he walks along the circular path."
P[r_conanx]="$H He is seen in strict side profile facing LEFT, walking to the left, leaning far forward, both hands and his shoulder pressed against the side of the beam; his face shows exhausting strain: teeth gritted, eyes squeezed half shut, red cheeks, drops of sweat. $CAP On the right, $CO stands still with his arms crossed, watching him sternly, not pushing. Each person wears only his own clothes. In the sky flies a long serpentine luck dragon with no wings at all, covered in white fur and pearly pink scales, with a big friendly dog-like head and floppy ears, undulating through the air like a snake. On the horizon, a dark swirling void of nothingness eats the landscape. $ST"; R[r_conanx]=hero_s2/sel_profile_left.png
P[r_conany]="$H He is seen in side profile facing LEFT, bent forward like a man pushing a heavy turnstile, his chest against the side of a beam that comes toward us; his face shows exhausting strain: teeth gritted, eyes squeezed half shut, red cheeks, drops of sweat. $CAP On the far right, $CO stands still with his arms crossed, watching him sternly, not pushing. Each person wears only his own clothes. In the sky flies a long serpentine luck dragon with no wings at all, covered in white fur and pearly pink scales, with a big friendly dog-like head and floppy ears. On the horizon, a dark swirling void of nothingness eats the landscape. $ST"; R[r_conany]=hero_s2/sel_profile_left.png
ids=("$@"); [ ${#ids} -eq 0 ] && ids=(r_dexterw r_conanw)
for id in $ids; do
  for s in 1 2; do
    out="${id}_$s.png"; [ -f "$out" ] && continue
    seed=$(( ${#id} * 1000 + s * 137 + 6161 ))
    flux-image "${P[$id]}" -i "${R[$id]}" -s 1280x720 --seed $seed -o "$out" >/dev/null 2>&1
    echo "$(date +%H:%M:%S) ok $out"
  done
done
